     1→// 桐城自摸麻将 - 局域网服务器
     2→// 运行方式: node majiang-server.js
     3→
     4→const http = require('http');
     5→const fs = require('fs');
     6→const path = require('path');
     7→const WebSocket = require('ws');
     8→
     9→const PORT = 8082;
    10→
    11→// ==================== HTTP服务器 ====================
    12→const server = http.createServer((req, res) => {
    13→    console.log(`HTTP请求: ${req.url}`);
    14→
    15→    if (req.url === '/' || req.url === '/index.html') {
    16→        const htmlPath = path.join(__dirname, 'majiang-lan.html');
    17→        fs.readFile(htmlPath, (err, data) => {
    18→            if (err) {
    19→                res.writeHead(404);
    20→                res.end('游戏文件未找到');
    21→                return;
    22→            }
    23→            res.writeHead(200, {
    24→                'Content-Type': 'text/html; charset=utf-8'
    25→            });
    26→            res.end(data);
    27→        });
    28→    } else if (req.url === '/favicon.ico') {
    29→        res.writeHead(204);
    30→        res.end();
    31→    } else {
    32→        res.writeHead(404);
    33→        res.end('Not Found');
    34→    }
    35→});
    36→
    37→// ==================== WebSocket服务器 ====================
    38→const wss = new WebSocket.Server({ server });
    39→
    40→// 游戏房间管理
    41→const tables = new Map();
    42→const playerToTable = new Map();
    43→let tableCounter = 0;
    44→
    45→// 所有已登录的客户端（用于广播牌桌列表）
    46→const loggedInClients = new Set();
    47→
    48→// ==================== 牌面常量 ====================
    49→const SUITS = ['筒', '条', '万'];
    50→const RANKS = [1, 2, 3, 4, 5, 6, 7, 8, 9];
    51→const WINDS = ['东', '南', '西', '北'];
    52→const ARROWS = ['中', '发', '白'];
    53→
    54→// 创建一副麻将牌
    55→function createDeck() {
    56→    const deck = [];
    57→
    58→    // 筒条万 (每种4张)
    59→    for (const suit of SUITS) {
    60→        for (const rank of RANKS) {
    61→            for (let i = 0; i < 4; i++) {
    62→                deck.push({
    63→                    suit,
    64→                    rank,
    65→                    type: 'number',
    66→                    id: `${suit}${rank}_${i}`
    67→                });
    68→            }
    69→        }
    70→    }
    71→
    72→    // 风牌 (每种4张)
    73→    for (const wind of WINDS) {
    74→        for (let i = 0; i < 4; i++) {
    75→            deck.push({
    76→                suit: '风',
    77→                rank: wind,
    78→                type: 'wind',
    79→                id: `风${wind}_${i}`
    80→            });
    81→        }
    82→    }
    83→
    84→    // 箭牌 (每种4张)
    85→    for (const arrow of ARROWS) {
    86→        for (let i = 0; i < 4; i++) {
    87→            deck.push({
    88→                suit: '箭',
    89→                rank: arrow,
    90→                type: 'arrow',
    91→                id: `箭${arrow}_${i}`
    92→            });
    93→        }
    94→    }
    95→
    96→    return deck; // 136张
    97→}
    98→
    99→// 洗牌
   100→function shuffle(deck) {
   101→    const shuffled = [...deck];
   102→    for (let i = shuffled.length - 1; i > 0; i--) {
   103→        const j = Math.floor(Math.random() * (i + 1));
   104→        [shuffled[i], shuffled[j]] = [shuffled[j], shuffled[i]];
   105→    }
   106→    return shuffled;
   107→}
   108→
   109→// 牌的显示名称
   110→function cardName(card) {
   111→    if (card.type === 'number') {
   112→        return `${card.rank}${card.suit}`;
   113→    } else {
   114→        return card.rank;
   115→    }
   116→}
   117→
   118→// ==================== 牌桌类 ====================
   119→class GameTable {
   120→    constructor(id, tableNumber) {
   121→        this.id = id;
   122→        this.tableNumber = tableNumber;
   123→        this.players = new Map(); // playerId -> player info
   124→        this.spectators = new Map();
   125→        this.maxPlayers = 4;
   126→        this.gameTimer = null; // 游戏计时器
   127→        this.lastSeatShuffleTime = Date.now(); // 上次换座位时间
   128→        this.sessionStartTime = Date.now(); // 会话开始时间
   129→
   130→        this.gameState = {
   131→            started: false,
   132→            currentPlayer: 0, // 0-3, 当前出牌玩家索引
   133→            dealer: 0, // 庄家索引
   134→            deck: [], // 牌堆
   135→            hands: {}, // playerId -> cards[]
   136→            wildCard: null, // 万能牌
   137→            discardedPile: [], // 打出的牌
   138→            showedCards: {}, // playerId -> { fa: [], gang: [] }
   139→            faUsed: {}, // playerId -> 玩家是否已换过发
   140→            lastDrawn: null, // 最后摸的牌
   141→            gameStartTime: null, // 游戏开始时间
   142→            totalGameTime: 0 // 游戏总时长（秒）
   143→        };
   144→    }
   145→
   146→    // 获取按座位排序的玩家ID数组
   147→    getSortedPlayerIds() {
   148→        return Array.from(this.players.entries())
   149→            .sort((a, b) => a[1].seatNum - b[1].seatNum)
   150→            .map(([id]) => id);
   151→    }
   152→
   153→    // 添加玩家
   154→    addPlayer(ws, playerId, playerName, seatNum = null) {
   155→        if (this.players.size >= this.maxPlayers) return false;
   156→        if (this.gameState.started) return false;
   157→
   158→        let actualSeat;
   159→        if (seatNum !== null && seatNum >= 1 && seatNum <= 4) {
   160→            const occupied = Array.from(this.players.values()).some(p => p.seatNum === seatNum);
   161→            if (occupied) return false;
   162→            actualSeat = seatNum;
   163→        } else {
   164→            const occupiedSeats = new Set(Array.from(this.players.values()).map(p => p.seatNum));
   165→            for (let i = 1; i <= 4; i++) {
   166→                if (!occupiedSeats.has(i)) {
   167→                    actualSeat = i;
   168→                    break;
   169→                }
   170→            }
   171→        }
   172→
   173→        this.players.set(playerId, {
   174→            ws,
   175→            id: playerId,
   176→            name: playerName,
   177→            seatNum: actualSeat,
   178→            ready: false,
   179→            isAI: false
   180→        });
   181→
   182→        return true;
   183→    }
   184→
   185→    // 移除玩家
   186→    removePlayer(playerId) {
   187→        this.players.delete(playerId);
   188→        return this.players.size === 0;
   189→    }
   190→
   191→    // 设置准备状态
   192→    setPlayerReady(playerId, ready) {
   193→        const player = this.players.get(playerId);
   194→        if (player) {
   195→            player.ready = ready;
   196→            this.broadcastPlayerList();
   197→            this.checkStartGame();
   198→        }
   199→    }
   200→
   201→    // 检查是否可以开始游戏
   202→    checkStartGame() {
   203→        const allReady = Array.from(this.players.values()).every(p => p.ready);
   204→        if (allReady && this.players.size === 4 && !this.gameState.started) {
   205→            // 检查是否需要随机换座位（每隔1小时）
   206→            const timeSinceLastShuffle = Date.now() - this.lastSeatShuffleTime;
   207→            if (timeSinceLastShuffle >= 3600000) { // 1小时 = 3600000毫秒
   208→                this.randomizeSeats();
   209→                this.lastSeatShuffleTime = Date.now();
   210→                this.broadcastMessage('⏰ 游戏已进行1小时，座位已随机更换！');
   211→            }
   212→            this.startGame();
   213→        }
   214→    }
   215→
   216→    // 随机换座位
   217→    randomizeSeats() {
   218→        const playerList = Array.from(this.players.values());
   219→        const seats = [1, 2, 3, 4];
   220→
   221→        // 洗牌座位
   222→        for (let i = seats.length - 1; i > 0; i--) {
   223→            const j = Math.floor(Math.random() * (i + 1));
   224→            [seats[i], seats[j]] = [seats[j], seats[i]];
   225→        }
   226→
   227→        // 分配新座位
   228→        playerList.forEach((player, index) => {
   229→            player.seatNum = seats[index];
   230→        });
   231→
   232→        console.log(`牌桌${this.tableNumber} 座位已随机更换`);
   233→        this.broadcastPlayerList();
   234→    }
   235→
   236→    // 开始游戏
   237→    startGame() {
   238→        this.gameState.started = true;
   239→        this.gameState.gameStartTime = Date.now();
   240→        this.gameState.totalGameTime = 0;
   241→
   242→        // 启动游戏计时器（每秒更新）
   243→        this.gameTimer = setInterval(() => {
   244→            if (this.gameState.started) {
   245→                this.gameState.totalGameTime = Math.floor((Date.now() - this.gameState.gameStartTime) / 1000);
   246→            }
   247→        }, 1000);
   248→
   249→        // 洗牌
   250→        this.gameState.deck = shuffle(createDeck());
   251→
   252→        // 确定万能牌（随机翻一张）
   253→        const wildIndex = Math.floor(Math.random() * this.gameState.deck.length);
   254→        this.gameState.wildCard = this.gameState.deck[wildIndex];
   255→
   256→        // 初始化手牌和展示区
   257→        const playerIds = this.getSortedPlayerIds();
   258→        for (const pid of playerIds) {
   259→            this.gameState.hands[pid] = [];
   260→            this.gameState.showedCards[pid] = { fa: [], gang: [] };
   261→            this.gameState.faUsed[pid] = false;
   262→        }
   263→
   264→        // 发牌：每人4张×3轮，然后每人1张，庄家多1张
   265→        // 庄家是1号位(seatNum=1)，对应索引0
   266→        const dealerIndex = playerIds.findIndex(pid => this.players.get(pid).seatNum === 1);
   267→        this.gameState.dealer = dealerIndex >= 0 ? dealerIndex : 0;
   268→
   269→        // 每人4张×3轮
   270→        for (let round = 0; round < 3; round++) {
   271→            for (const pid of playerIds) {
   272→                for (let i = 0; i < 4; i++) {
   273→                    const card = this.gameState.deck.pop();
   274→                    if (card) this.gameState.hands[pid].push(card);
   275→                }
   276→            }
   277→        }
   278→
   279→        // 每人1张
   280→        for (const pid of playerIds) {
   281→            const card = this.gameState.deck.pop();
   282→            if (card) this.gameState.hands[pid].push(card);
   283→        }
   284→
   285→        // 庄家多拿1张
   286→        const dealerPid = playerIds[this.gameState.dealer];
   287→        const extraCard = this.gameState.deck.pop();
   288→        if (extraCard) this.gameState.hands[dealerPid].push(extraCard);
   289→
   290→        // 庄家先出牌
   291→        this.gameState.currentPlayer = this.gameState.dealer;
   292→
   293→        // 排序手牌
   294→        for (const pid of playerIds) {
   295→            this.sortHand(pid);
   296→        }
   297→
   298→        console.log(`牌桌${this.tableNumber} 游戏开始，万能牌: ${cardName(this.gameState.wildCard)}`);
   299→
   300→        // 先发送发牌动画消息
   301→        this.broadcastDealStart();
   302→
   303→        // 等待发牌动画完成（约3秒）后发送游戏状态
   304→        setTimeout(() => {
   305→            this.broadcastGameState();
   306→        }, 3000);
   307→    }
   308→
   309→    // 广播发牌开始消息
   310→    broadcastDealStart() {
   311→        const message = JSON.stringify({ type: 'dealStart' });
   312→        for (const player of this.players.values()) {
   313→            if (player.ws && player.ws.readyState === WebSocket.OPEN) {
   314→                player.ws.send(message);
   315→            }
   316→        }
   317→    }
   318→
   319→    // 排序手牌
   320→    sortHand(playerId) {
   321→        const hand = this.gameState.hands[playerId];
   322→        if (!hand) return;
   323→
   324→        const suitOrder = { '筒': 0, '条': 1, '万': 2, '风': 3, '箭': 4 };
   325→        const windOrder = { '东': 0, '南': 1, '西': 2, '北': 3 };
   326→        const arrowOrder = { '中': 0, '发': 1, '白': 2 };
   327→
   328→        hand.sort((a, b) => {
   329→            // 万能牌放最后
   330→            if (this.isWildCard(a) && !this.isWildCard(b)) return 1;
   331→            if (!this.isWildCard(a) && this.isWildCard(b)) return -1;
   332→
   333→            const suitA = suitOrder[a.suit] ?? 5;
   334→            const suitB = suitOrder[b.suit] ?? 5;
   335→            if (suitA !== suitB) return suitA - suitB;
   336→
   337→            if (a.type === 'number' && b.type === 'number') {
   338→                return a.rank - b.rank;
   339→            } else if (a.type === 'wind' && b.type === 'wind') {
   340→                return (windOrder[a.rank] ?? 0) - (windOrder[b.rank] ?? 0);
   341→            } else if (a.type === 'arrow' && b.type === 'arrow') {
   342→                return (arrowOrder[a.rank] ?? 0) - (arrowOrder[b.rank] ?? 0);
   343→            }
   344→            return 0;
   345→        });
   346→    }
   347→
   348→    // 判断是否是万能牌（相同牌或红中）
   349→    isWildCard(card) {
   350→        const wild = this.gameState.wildCard;
   351→        if (!wild) return false;
   352→
   353→        // 相同牌是万能牌
   354→        if (card.suit === wild.suit && card.rank === wild.rank) return true;
   355→        // 红中也是万能牌
   356→        if (card.type === 'arrow' && card.rank === '中') return true;
   357→
   358→        return false;
   359→    }
   360→
   361→    // 摸牌
   362→    drawCard(playerId) {
   363→        if (this.gameState.deck.length === 0) {
   364→            return null; // 流局
   365→        }
   366→
   367→        const card = this.gameState.deck.pop();
   368→        if (card) {
   369→            this.gameState.hands[playerId].push(card);
   370→            this.gameState.lastDrawn = card;
   371→            this.sortHand(playerId);
   372→        }
   373→        return card;
   374→    }
   375→
   376→    // 出牌
   377→    playCard(playerId, cardId) {
   378→        const hand = this.gameState.hands[playerId];
   379→        if (!hand) return false;
   380→
   381→        const cardIndex = hand.findIndex(c => c.id === cardId);
   382→        if (cardIndex === -1) return false;
   383→
   384→        const card = hand.splice(cardIndex, 1)[0];
   385→
   386→        // 打出的牌背面朝上，加入弃牌堆
   387→        this.gameState.discardedPile.push({
   388→            playerId,
   389→            card,
   390→            hidden: true // 背面朝上
   391→        });
   392→
   393→        // 下一位玩家
   394→        this.nextPlayer();
   395→
   396→        return true;
   397→    }
   398→
   399→    // 换牌（发或红中）
   400→    changeFa(playerId) {
   401→        // 检查是否已换过
   402→        if (this.gameState.faUsed[playerId]) return false;
   403→
   404→        const hand = this.gameState.hands[playerId];
   405→        if (!hand) return false;
   406→
   407→        const wild = this.gameState.wildCard;
   408→        const isWildFa = wild && wild.type === 'arrow' && wild.rank === '发';
   409→
   410→        // 如果万能牌是"发"，找红中；否则找"发"
   411→        let targetRank = isWildFa ? '中' : '发';
   412→        const faIndex = hand.findIndex(c => c.type === 'arrow' && c.rank === targetRank);
   413→        if (faIndex === -1) return false;
   414→
   415→        // 移出牌到展示区
   416→        const faCard = hand.splice(faIndex, 1)[0];
   417→        this.gameState.showedCards[playerId].fa.push(faCard);
   418→        this.gameState.faUsed[playerId] = true;
   419→
   420→        // 摸一张新牌
   421→        const newCard = this.drawCard(playerId);
   422→
   423→        return { faCard, newCard };
   424→    }
   425→
   426→    // 暗杠
   427→    doGang(playerId, cardId) {
   428→        const hand = this.gameState.hands[playerId];
   429→        if (!hand) return false;
   430→
   431→        // 找到这张牌
   432→        const targetCard = hand.find(c => c.id === cardId);
   433→        if (!targetCard) return false;
   434→
   435→        // 找所有相同的牌（不包括万能牌替代）
   436→        const sameCards = hand.filter(c =>
   437→            c.suit === targetCard.suit && c.rank === targetCard.rank
   438→        );
   439→
   440→        if (sameCards.length !== 4) return false;
   441→
   442→        // 移除这4张牌
   443→        this.gameState.hands[playerId] = hand.filter(c =>
   444→            !(c.suit === targetCard.suit && c.rank === targetCard.rank)
   445→        );
   446→
   447→        // 加入展示区
   448→        this.gameState.showedCards[playerId].gang.push(sameCards);
   449→
   450→        return sameCards;
   451→    }
   452→
   453→    // 检查是否可以暗杠
   454→    canGang(playerId) {
   455→        const hand = this.gameState.hands[playerId];
   456→        if (!hand) return [];
   457→
   458→        const counts = {};
   459→        for (const card of hand) {
   460→            const key = `${card.suit}_${card.rank}`;
   461→            counts[key] = (counts[key] || 0) + 1;
   462→        }
   463→
   464→        const gangable = [];
   465→        for (const [key, count] of Object.entries(counts)) {
   466→            if (count === 4) {
   467→                const [suit, rank] = key.split('_');
   468→                gangable.push({ suit, rank });
   469→            }
   470→        }
   471→
   472→        return gangable;
   473→    }
   474→
   475→    // 检查是否有牌可以换（发或红中）
   476→    hasFa(playerId) {
   477→        const hand = this.gameState.hands[playerId];
   478→        if (!hand) return false;
   479→
   480→        // 如果已经换过，不能换
   481→        if (this.gameState.faUsed[playerId]) return false;
   482→
   483→        const wild = this.gameState.wildCard;
   484→        const isWildFa = wild && wild.type === 'arrow' && wild.rank === '发';
   485→
   486→        // 如果万能牌是"发"，用红中换牌；否则用"发"换牌
   487→        if (isWildFa) {
   488→            return hand.some(c => c.type === 'arrow' && c.rank === '中');
   489→        } else {
   490→            return hand.some(c => c.type === 'arrow' && c.rank === '发');
   491→        }
   492→    }
   493→
   494→    // 获取当前用于换牌的牌名（发或中）
   495→    getExchangeCardName() {
   496→        const wild = this.gameState.wildCard;
   497→        const isWildFa = wild && wild.type === 'arrow' && wild.rank === '发';
   498→        return isWildFa ? '中' : '发';
   499→    }
   500→
   501→    // 下一位玩家
   502→    nextPlayer() {
   503→        this.gameState.currentPlayer = (this.gameState.currentPlayer + 1) % 4;
   504→    }
   505→
   506→    // 获取当前玩家ID
   507→    getCurrentPlayerId() {
   508→        const playerIds = this.getSortedPlayerIds();
   509→        return playerIds[this.gameState.currentPlayer];
   510→    }
   511→
   512→    // 广播玩家列表
   513→    broadcastPlayerList() {
   514→        const players = Array.from(this.players.values()).map(p => ({
   515→            id: p.id,
   516→            name: p.name,
   517→            seatNum: p.seatNum,
   518→            ready: p.ready,
   519→            isAI: p.isAI
   520→        }));
   521→
   522→        const message = JSON.stringify({
   523→            type: 'playerList',
   524→            players,
   525→            tableNumber: this.tableNumber,
   526→            started: this.gameState.started
   527→        });
   528→
   529→        for (const player of this.players.values()) {
   530→            if (player.ws && player.ws.readyState === WebSocket.OPEN) {
   531→                player.ws.send(message);
   532→            }
   533→        }
   534→
   535→        for (const spectator of this.spectators.values()) {
   536→            if (spectator.ws && spectator.ws.readyState === WebSocket.OPEN) {
   537→                spectator.ws.send(message);
   538→            }
   539→        }
   540→    }
   541→
   542→    // 广播游戏状态
   543→    broadcastGameState() {
   544→        const playerIds = this.getSortedPlayerIds();
   545→
   546→        // 调试：打印万能牌信息
   547→        console.log(`广播游戏状态，万能牌: ${JSON.stringify(this.gameState.wildCard)}`);
   548→
   549→        for (const [playerId, player] of this.players) {
   550→            if (!player.ws || player.ws.readyState !== WebSocket.OPEN) continue;
   551→
   552→            const state = this.getPlayerGameState(playerId);
   553→            console.log(`发送游戏状态给 ${player.name}: 手牌数量=${state.myHand.length}, 万能牌: ${JSON.stringify(state.wildCard)}`);
   554→            player.ws.send(JSON.stringify({
   555→                type: 'gameState',
   556→                data: state
   557→            }));
   558→        }
   559→    }
   560→
   561→    // 获取单个玩家视角的游戏状态
   562→    getPlayerGameState(playerId) {
   563→        const playerIds = this.getSortedPlayerIds();
   564→        const myIndex = playerIds.indexOf(playerId);
   565→
   566→        // 构建各玩家信息
   567→        const playerInfo = {};
   568→        for (let i = 0; i < playerIds.length; i++) {
   569→            const pid = playerIds[i];
   570→            const p = this.players.get(pid);
   571→            playerInfo[pid] = {
   572→                name: p?.name || '',
   573→                seatNum: p?.seatNum || (i + 1),
   574→                handCount: this.gameState.hands[pid]?.length || 0,
   575→                showedCards: this.gameState.showedCards[pid] || { fa: [], gang: [] }
   576→            };
   577→        }
   578→
   579→        // 只返回自己的手牌
   580→        const myHand = this.gameState.hands[playerId] || [];
   581→
   582→        // 获取当前玩家的座位号
   583→        const currentPid = playerIds[this.gameState.currentPlayer];
   584→        const currentPlayerSeat = this.players.get(currentPid)?.seatNum || 1;
   585→
   586→        // 获取庄家的座位号
   587→        const dealerPid = playerIds[this.gameState.dealer];
   588→        const dealerSeat = this.players.get(dealerPid)?.seatNum || 1;
   589→
   590→        return {
   591→            started: this.gameState.started,
   592→            currentPlayer: this.gameState.currentPlayer,
   593→            currentPlayerSeat,
   594→            dealer: this.gameState.dealer,
   595→            dealerSeat,
   596→            myIndex,
   597→            myHand,
   598→            wildCard: this.gameState.wildCard,
   599→            deckCount: this.gameState.deck.length,
   600→            totalGameTime: this.gameState.totalGameTime,
   601→            playerInfo,
   602→            discardedCount: this.gameState.discardedPile.length,
   603→            canChangeFa: this.hasFa(playerId) && this.getCurrentPlayerId() === playerId,
   604→            canGang: this.canGang(playerId).length > 0 && this.getCurrentPlayerId() === playerId
   605→        };
   606→    }
   607→
   608→    // 广播消息
   609→    broadcastMessage(text) {
   610→        const message = JSON.stringify({ type: 'message', text });
   611→        for (const player of this.players.values()) {
   612→            if (player.ws && player.ws.readyState === WebSocket.OPEN) {
   613→                player.ws.send(message);
   614→            }
   615→        }
   616→    }
   617→
   618→    // 获取牌桌信息（用于大厅显示）
   619→    getTableInfo() {
   620→        return {
   621→            id: this.id,
   622→            tableNumber: this.tableNumber,
   623→            playerCount: this.players.size,
   624→            maxPlayers: this.maxPlayers,
   625→            started: this.gameState.started,
   626→            deckCount: this.gameState.deck ? this.gameState.deck.length : 0,
   627→            players: Array.from(this.players.values()).map(p => ({
   628→                name: p.name,
   629→                seatNum: p.seatNum,
   630→                ready: p.ready
   631→            }))
   632→        };
   633→    }
   634→}
   635→
   636→// ==================== WebSocket连接处理 ====================
   637→wss.on('connection', (ws) => {
   638→    let playerId = null;
   639→    let playerName = null;
   640→    let currentTableId = null;
   641→
   642→    console.log('新客户端连接');
   643→
   644→    ws.on('message', (data) => {
   645→        try {
   646→            const msg = JSON.parse(data);
   647→
   648→            switch (msg.type) {
   649→                case 'login':
   650→                    playerId = `player_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
   651→                    playerName = msg.name || '玩家';
   652→
   653→                    // 添加到已登录客户端集合
   654→                    loggedInClients.add(ws);
   655→
   656→                    ws.send(JSON.stringify({
   657→                        type: 'loginSuccess',
   658→                        playerId,
   659→                        playerName
   660→                    }));
   661→
   662→                    // 发送牌桌列表
   663→                    sendTableList(ws);
   664→                    break;
   665→
   666→                case 'getTableList':
   667→                    sendTableList(ws);
   668→                    break;
   669→
   670→                case 'createTable':
   671→                    const newTable = createTable();
   672→                    // 加入牌桌
   673→                    if (joinTable(ws, playerId, playerName, newTable.id, msg.seatNum)) {
   674→                        currentTableId = newTable.id;
   675→                    }
   676→                    // 广播牌桌列表更新给所有人
   677→                    broadcastTableList();
   678→                    break;
   679→
   680→                case 'joinTable':
   681→                    if (joinTable(ws, playerId, playerName, msg.tableId, msg.seatNum)) {
   682→                        currentTableId = msg.tableId;
   683→                        // 广播牌桌列表更新给所有人
   684→                        broadcastTableList();
   685→                    }
   686→                    break;
   687→
   688→                case 'ready':
   689→                    if (currentTableId) {
   690→                        const table = tables.get(currentTableId);
   691→                        if (table) {
   692→                            table.setPlayerReady(playerId, msg.ready);
   693→                        }
   694→                    }
   695→                    break;
   696→
   697→                case 'play':
   698→                    if (currentTableId) {
   699→                        const table = tables.get(currentTableId);
   700→                        if (table && table.getCurrentPlayerId() === playerId) {
   701→                            if (table.playCard(playerId, msg.cardId)) {
   702→                                table.broadcastGameState();
   703→                            }
   704→                        }
   705→                    }
   706→                    break;
   707→
   708→                case 'changeFa':
   709→                    if (currentTableId) {
   710→                        const table = tables.get(currentTableId);
   711→                        if (table && table.getCurrentPlayerId() === playerId) {
   712→                            const result = table.changeFa(playerId);
   713→                            if (result) {
   714→                                table.broadcastMessage(`${playerName} 换了一张"發"`);
   715→                                table.broadcastGameState();
   716→                            }
   717→                        }
   718→                    }
   719→                    break;
   720→
   721→                case 'gang':
   722→                    if (currentTableId) {
   723→                        const table = tables.get(currentTableId);
   724→                        if (table && table.getCurrentPlayerId() === playerId) {
