   728→                                table.broadcastGameState();
   729→                            }
   730→                        }
   731→                    }
   732→                    break;
   733→
   734→                case 'draw':
   735→                    if (currentTableId) {
   736→                        const table = tables.get(currentTableId);
   737→                        if (table && table.getCurrentPlayerId() === playerId) {
   738→                            const card = table.drawCard(playerId);
