   741→                            } else {
   742→                                table.broadcastMessage('牌堆已空，流局！');
   743→                            }
   744→                        }
   745→                    }
   746→                    break;
   747→
   748→                case 'chat':
   749→                    if (currentTableId) {
   750→                        const table = tables.get(currentTableId);
   751→                        if (table) {
   752→                            table.broadcastMessage(`${playerName}: ${msg.text}`);
   753→                        }
   754→                    }
   755→                    break;
   756→            }
   757→        } catch (e) {
   758→            console.error('消息处理错误:', e);
   759→        }
   760→    });
   761→
   762→    ws.on('close', () => {
   763→        console.log('客户端断开:', playerName);
   764→
   765→        // 从已登录客户端集合中移除
   766→        loggedInClients.delete(ws);
   767→
   768→        if (currentTableId && playerId) {
   769→            const table = tables.get(currentTableId);
   770→            if (table) {
   771→                // 游戏进行中不删除玩家，只标记断开
   772→                const player = table.players.get(playerId);
   773→                if (player) {
   774→                    player.ws = null;
   775→                    player.ready = false;
   776→                }
   777→
   778→                // 如果游戏未开始且房间为空，删除房间
   779→                if (!table.gameState.started && table.removePlayer(playerId)) {
   780→                    tables.delete(currentTableId);
   781→                    console.log(`牌桌 ${currentTableId} 已删除`);
   782→                }
   783→
   784→                table.broadcastPlayerList();
   785→            }
   786→            playerToTable.delete(playerId);
   787→
   788→            // 广播牌桌列表更新（因为有人离开）
   789→            broadcastTableList();
   790→        }
   791→    });
   792→});
   793→
   794→// 发送牌桌列表
   795→function sendTableList(ws) {
   796→    const tableList = Array.from(tables.values()).map(t => t.getTableInfo());
   797→    ws.send(JSON.stringify({
   798→        type: 'tableList',
   799→        tables: tableList
   800→    }));
   801→}
   802→
   803→// 广播牌桌列表给所有已登录客户端
   804→function broadcastTableList() {
   805→    const tableList = Array.from(tables.values()).map(t => t.getTableInfo());
   806→    const message = JSON.stringify({
   807→        type: 'tableList',
   808→        tables: tableList
   809→    });
   810→
   811→    for (const client of loggedInClients) {
   812→        if (client.readyState === WebSocket.OPEN) {
   813→            client.send(message);
   814→        }
   815→    }
   816→    console.log(`广播牌桌列表给 ${loggedInClients.size} 个客户端，当前牌桌数: ${tableList.length}`);
   817→}
   818→
   819→// 创建牌桌
   820→function createTable() {
   821→    tableCounter++;
   822→    const tableId = `table_${tableCounter}`;
   823→    const table = new GameTable(tableId, tableCounter);
   824→    tables.set(tableId, table);
   825→    console.log(`创建新牌桌: ${tableId}`);
   826→    return table;
   827→}
   828→
   829→// 加入牌桌
   830→function joinTable(ws, playerId, playerName, tableId, seatNum) {
   831→    const table = tables.get(tableId);
   832→    if (!table) {
   833→        ws.send(JSON.stringify({ type: 'error', message: '牌桌不存在' }));
   834→        return false;
   835→    }
   836→
   837→    if (table.addPlayer(ws, playerId, playerName, seatNum)) {
   838→        playerToTable.set(playerId, tableId);
   839→        table.broadcastPlayerList();
   840→        console.log(`${playerName} 加入牌桌 ${tableId}`);
   841→        return true;
   842→    } else {
   843→        ws.send(JSON.stringify({ type: 'error', message: '无法加入牌桌（已满或游戏已开始）' }));
   844→        return false;
   845→    }
   846→}
   847→
   848→// 获取本机IP
   849→function getLocalIP() {
   850→    const os = require('os');
   851→    const interfaces = os.networkInterfaces();
   852→
   853→    for (const name of Object.keys(interfaces)) {
   854→        for (const iface of interfaces[name]) {
   855→            if (iface.family === 'IPv4' && !iface.internal) {
   856→                return iface.address;
   857→            }
