   872→
   873→// 定时清理空桌子（每5分钟检查一次）
   874→setInterval(() => {
   875→    for (const [tableId, table] of tables) {
   876→        // 如果桌子没有玩家，或者所有玩家都已断开连接
   877→        if (table.players.size === 0) {
   878→            tables.delete(tableId);
   879→            console.log(`Cleaned up empty table: ${tableId}`);
   880→        } else {
