  1151→  1151→        // 连接WebSocket
  1152→  1152→        function connect() {
  1153→  1153→            const protocol = window.location.protocol === 'https:' ? 'wss:' : 'ws:';
  1154→  1154→            ws = new WebSocket(`${protocol}//${window.location.host}`);
  1155→  1155→
  1156→  1156→            ws.onopen = () => {
  1157→  1157→                console.log('WebSocket已连接');
  1158→  1158→            };
  1159→  1159→
  1160→  1160→            ws.onmessage = (event) => {
  1161→  1161→                const data = JSON.parse(event.data);
  1162→  1162→                handleMessage(data);
  1163→  1163→            };
  1164→  1164→
  1165→  1165→            ws.onclose = () => {
  1166→  1166→                console.log('WebSocket已断开');
