  1185→  1185→                    // 登录成功后获取牌桌列表
  1186→  1186→                    if (ws && ws.readyState === WebSocket.OPEN) {
  1187→  1187→                        ws.send(JSON.stringify({ type: 'getTableList' }));
  1188→  1188→                    }
  1189→  1189→                    break;
  1190→  1190→
  1191→  1191→                case 'tableList':
  1192→  1192→                    renderTableList(data.tables);
  1193→  1193→                    break;
  1194→  1194→
  1195→  1195→                case 'playerList':
  1196→  1196→                    renderPlayerList(data);
