  1198→  1198→
  1199→  1199→                case 'dealStart':
  1200→  1200→                    // 开始发牌动画
  1201→  1201→                    showDealAnimation();
  1202→  1202→                    break;
  1203→  1203→
  1204→  1204→                case 'gameState':
  1205→  1205→                    gameState = data.data;
  1206→  1206→                    myIndex = gameState.myIndex;
  1207→  1207→                    console.log('收到游戏状态:', gameState);
  1208→  1208→                    console.log('我的手牌:', gameState.myHand);
  1209→  1209→                    console.log('手牌数量:', gameState.myHand ? gameState.myHand.length : 0);
  1210→  1210→                    updateGameUI();
  1211→  1211→                    break;
  1212→  1212→
  1213→  1213→                case 'message':
  1214→  1214→                    addChatMessage(data.text);
  1215→  1215→                    break;
  1216→  1216→
  1217→  1217→                case 'error':
  1218→  1218→                    alert(data.message);
  1219→  1219→                    break;
  1220→  1220→            }
  1221→  1221→        }
  1222→  1222→
  1223→  1223→        // 确保已登录
  1224→  1224→        function ensureLogin(callback) {
  1225→  1225→            const name = document.getElementById('playerName').value.trim();
  1226→  1226→            if (!name) {
  1227→  1227→                alert('请先输入名称');
  1228→  1228→                return false;
  1229→  1229→            }
  1230→  1230→
  1231→  1231→            if (!playerId || !playerName) {
  1232→  1232→                playerName = name;
  1233→  1233→                if (!ws || ws.readyState !== WebSocket.OPEN) {
  1234→  1234→                    connect();
  1235→  1235→                    setTimeout(() => {
  1236→  1236→                        ws.send(JSON.stringify({ type: 'login', name }));
  1237→  1237→                        if (callback) setTimeout(callback, 300);
  1238→  1238→                    }, 500);
  1239→  1239→                } else {
  1240→  1240→                    ws.send(JSON.stringify({ type: 'login', name }));
  1241→  1241→                    if (callback) setTimeout(callback, 300);
  1242→  1242→                }
  1243→  1243→                return true;
  1244→  1244→            }
  1245→  1245→            return true;
  1246→  1246→        }
  1247→  1247→
  1248→  1248→        // 登录
  1249→  1249→        function login() {
  1250→  1250→            const name = document.getElementById('playerName').value.trim();
  1251→  1251→            if (!name) {
  1252→  1252→                alert('请输入名字');
  1253→  1253→                return;
