  1255→  1255→
  1256→  1256→            playerName = name;
  1257→  1257→            if (!ws || ws.readyState !== WebSocket.OPEN) {
  1258→  1258→                connect();
  1259→  1259→                setTimeout(() => {
  1260→  1260→                    ws.send(JSON.stringify({ type: 'login', name }));
  1261→  1261→                }, 500);
  1262→  1262→            } else {
  1263→  1263→                ws.send(JSON.stringify({ type: 'login', name }));
  1264→  1264→            }
  1265→  1265→        }
  1266→  1266→
  1267→  1267→        // 退出
