  1275→  1275→
  1276→  1276→        // 渲染牌桌列表
  1277→  1277→        function renderTableList(tables) {
  1278→  1278→            const container = document.getElementById('tableList');
  1279→  1279→            container.innerHTML = '';
  1280→  1280→
  1281→  1281→            // 创建新桌卡片
