  1288→  1288→            createCard.onclick = createTable;
  1289→  1289→            container.appendChild(createCard);
  1290→  1290→
  1291→  1291→            // 现有牌桌
  1292→  1292→            tables.forEach((table, index) => {
  1293→  1293→                const card = document.createElement('div');
