  1296→  1296→
  1297→  1297→                card.className = `table-card ${isFull ? 'full' : ''} ${isPlaying ? 'playing' : ''}`;
  1298→  1298→
  1299→  1299→                // 生成圆桌座位显示
  1300→  1300→                let seatsHtml = '';
  1301→  1301→                for (let i = 0; i < 4; i++) {
  1302→  1302→                    const seatNum = i + 1;
