  1304→  1304→                    const occupied = !!player;
  1305→  1305→                    const occupiedClass = occupied ? 'occupied' : '';
  1306→  1306→                    const clickHandler = (!occupied && !isPlaying) ? `onclick="event.stopPropagation(); joinTableById('${table.id}', ${seatNum})"` : '';
  1307→  1307→                    const title = occupied && player ? player.name : (isPlaying ? '' : '点击加入');
  1308→  1308→                    const displayChar = occupied ? (player ? player.name.charAt(0) : '?') : '+';
  1309→  1309→
  1310→  1310→                    seatsHtml += `
