// ==================== 胡牌判断算法 ====================

/**
 * 检查是否可以胡牌
 * @param {Array} hand - 手牌数组
 * @param {Object} wildCard - 万能牌
 * @param {Object} showedCards - 展示的牌（发、暗杠）
 * @returns {Object} { canHu: boolean, type: string, score: number }
 */
function checkHu(hand, wildCard, showedCards = { fa: [], gang: [] }) {
    // 复制手牌进行操作
    const tiles = [...hand];
    const wildCount = countWildCards(tiles, wildCard);

    // 1. 检查幺牌胡
    const yaoResult = checkYaoHu(tiles, wildCard);
    if (yaoResult.canHu) {
        return {
            canHu: true,
            type: '幺牌',
            score: calculateScore(showedCards, '幺牌')
        };
    }

    // 2. 检查浪牌胡
    const langResult = checkLangHu(tiles, wildCard);
    if (langResult.canHu) {
        return {
            canHu: true,
            type: '浪牌',
            score: calculateScore(showedCards, '浪牌')
        };
    }

    // 3. 检查七对胡
    const qiDuiResult = checkQiDuiHu(tiles, wildCard);
    if (qiDuiResult.canHu) {
        return {
            canHu: true,
            type: '七对',
            score: calculateScore(showedCards, '七对')
        };
    }

    // 4. 检查常规胡（4组+1将）
    const normalResult = checkNormalHu(tiles, wildCard);
    if (normalResult.canHu) {
        return {
            canHu: true,
            type: '常规',
            score: calculateScore(showedCards, '常规')
        };
    }

    return { canHu: false, type: null, score: 0 };
}

// 统计万能牌数量
function countWildCards(tiles, wildCard) {
    return tiles.filter(t => isWildCard(t, wildCard)).length;
}

// 判断是否是万能牌
function isWildCard(tile, wildCard) {
    if (!wildCard) return false;
    // 与翻出的牌相同
    if (tile.suit === wildCard.suit && String(tile.rank) === String(wildCard.rank)) {
        return true;
    }
    // 红中永远是万能牌
    if (tile.type === 'arrow' && tile.rank === '中') {
        return true;
    }
    return false;
}

// 判断是否是幺牌（1、9、风牌、箭牌）
function isYaoPai(tile) {
    if (tile.type === 'number') {
        return tile.rank === 1 || tile.rank === 9;
    }
    return true; // 风牌和箭牌都是幺牌
}

// 检查幺牌胡 - 全由幺牌组成
function checkYaoHu(tiles, wildCard) {
    for (const tile of tiles) {
        if (!isWildCard(tile, wildCard) && !isYaoPai(tile)) {
            return { canHu: false };
        }
    }
    // 幺牌胡没有张数要求，只要全是幺牌即可
    // 但需要凑成14张（含万能牌）
    return { canHu: tiles.length >= 14 };
}

// 检查浪牌胡
function checkLangHu(tiles, wildCard) {
    const nonWildTiles = tiles.filter(t => !isWildCard(t, wildCard));

    // 分类统计
    const tongCount = { suit: '筒', tiles: [] };
    const tiaoCount = { suit: '条', tiles: [] };
    const wanCount = { suit: '万', tiles: [] };
    const fengJianCount = []; // 风箭牌

    for (const tile of nonWildTiles) {
        if (tile.type === 'number') {
            if (tile.suit === '筒') tongCount.tiles.push(tile.rank);
            else if (tile.suit === '条') tiaoCount.tiles.push(tile.rank);
            else if (tile.suit === '万') wanCount.tiles.push(tile.rank);
        } else {
            fengJianCount.push(tile);
        }
    }

    // 检查数字牌是否符合浪牌规则（间隔组合）
    if (!checkLangSuit(tongCount.tiles) ||
        !checkLangSuit(tiaoCount.tiles) ||
        !checkLangSuit(wanCount.tiles)) {
        return { canHu: false };
    }

    // 检查数字牌数量限制（每种花色≤3张）
    if (tongCount.tiles.length > 3 || tiaoCount.tiles.length > 3 || wanCount.tiles.length > 3) {
        return { canHu: false };
    }

    // 检查风箭牌（各最多1张）
    const fengJianSet = new Set();
    for (const tile of fengJianCount) {
        const key = `${tile.suit}_${tile.rank}`;
        if (fengJianSet.has(key)) {
            return { canHu: false }; // 重复的风箭牌
        }
        fengJianSet.add(key);
    }

    // 总张数检查（加上万能牌应该等于14）
    const wildCardCount = countWildCards(tiles, wildCard);
    const totalCount = nonWildTiles.length + wildCardCount;
    if (totalCount < 14) {
        return { canHu: false };
    }

    return { canHu: true };
}

// 检查单个花色的浪牌规则（1-4-7, 2-5-8, 3-6-9）
function checkLangSuit(ranks) {
    const groups = { '1-4-7': 0, '2-5-8': 0, '3-6-9': 0 };

    for (const r of ranks) {
        if ([1, 4, 7].includes(r)) groups['1-4-7']++;
        else if ([2, 5, 8].includes(r)) groups['2-5-8']++;
        else if ([3, 6, 9].includes(r)) groups['3-6-9']++;
        else return false; // 不符合任何间隔组合
    }

    // 每组最多3张（1个完整的浪组合）
    for (const count of Object.values(groups)) {
        if (count > 3) return false;
    }

    return true;
}

// 检查七对胡
function checkQiDuiHu(tiles, wildCard) {
    const nonWildTiles = tiles.filter(t => !isWildCard(t, wildCard));
    const wildCount = tiles.length - nonWildTiles.length;

    // 统计每张牌的数量
    const counts = {};
    for (const tile of nonWildTiles) {
        const key = `${tile.suit}_${tile.rank}`;
        counts[key] = (counts[key] || 0) + 1;
    }

    let pairs = 0;
    let singles = 0;

    for (const count of Object.values(counts)) {
        pairs += Math.floor(count / 2);
        singles += count % 2;
    }

    // 万能牌可以配对单张
    const neededWild = singles;
    if (wildCount >= neededWild) {
        pairs += Math.floor((wildCount - neededWild) / 2) + neededWild;
    }

    return { canHu: pairs >= 7 };
}

// 检查常规胡（4组面子+1对将）
function checkNormalHu(tiles, wildCard) {
    const nonWildTiles = tiles.filter(t => !isWildCard(t, wildCard));
    const wildCount = tiles.length - nonWildTiles.length;

    // 统计每张牌的数量
    const counts = {};
    for (const tile of nonWildTiles) {
        const key = `${tile.suit}_${tile.rank}_${tile.type}`;
        if (!counts[key]) {
            counts[key] = { count: 0, tile };
        }
        counts[key].count++;
    }

    // 尝试每种牌作为将
    const allKeys = Object.keys(counts);
    allKeys.push('wild'); // 也尝试用万能牌做将

    for (const jiangKey of allKeys) {
        const tempCounts = JSON.parse(JSON.stringify(counts));
        let tempWild = wildCount;

        // 移除将
        if (jiangKey === 'wild') {
            if (tempWild >= 2) {
                tempWild -= 2;
            } else if (tempWild === 1) {
                // 找一张单牌配对
                let found = false;
                for (const k of Object.keys(tempCounts)) {
                    if (tempCounts[k].count === 1) {
                        tempCounts[k].count = 0;
                        tempWild--;
                        found = true;
                        break;
                    }
                }
                if (!found) continue;
            } else {
                continue;
            }
        } else {
            if (tempCounts[jiangKey].count >= 2) {
                tempCounts[jiangKey].count -= 2;
            } else if (tempCounts[jiangKey].count === 1 && tempWild >= 1) {
                tempCounts[jiangKey].count = 0;
                tempWild--;
            } else {
                continue;
            }
        }

        // 尝试组成4个面子
        if (tryFormMianzi(tempCounts, tempWild, 4)) {
            return { canHu: true };
        }
    }

    return { canHu: false };
}

// 递归尝试组成面子
function tryFormMianzi(counts, wildCount, needed) {
    if (needed === 0) return true;

    // 找剩余的牌
    const keys = Object.keys(counts).filter(k => counts[k].count > 0);
    if (keys.length === 0) {
        // 没有牌了，用万能牌组成面子
        return wildCount >= needed * 3;
    }

    const firstKey = keys[0];
    const tile = counts[firstKey].tile;
    const count = counts[firstKey].count;

    // 尝试刻子
    const tempCounts1 = JSON.parse(JSON.stringify(counts));
    let tempWild1 = wildCount;
    if (count >= 3) {
        tempCounts1[firstKey].count -= 3;
        if (tryFormMianzi(tempCounts1, tempWild1, needed - 1)) {
            return true;
        }
    } else if (count === 2 && tempWild1 >= 1) {
        tempCounts1[firstKey].count = 0;
        tempWild1--;
        if (tryFormMianzi(tempCounts1, tempWild1, needed - 1)) {
            return true;
        }
    } else if (count === 1 && tempWild1 >= 2) {
        tempCounts1[firstKey].count = 0;
        tempWild1 -= 2;
        if (tryFormMianzi(tempCounts1, tempWild1, needed - 1)) {
            return true;
        }
    }

    // 尝试顺子（仅数字牌）
    if (tile.type === 'number') {
        const suit = tile.suit;
        const rank = tile.rank;

        if (rank <= 7) { // 可以组成顺子
            const key1 = `${suit}_${rank}_${tile.type}`;
            const key2 = `${suit}_${rank + 1}_${tile.type}`;
            const key3 = `${suit}_${rank + 2}_${tile.type}`;

            const tempCounts2 = JSON.parse(JSON.stringify(counts));
            let tempWild2 = wildCount;
            let canForm = true;
            let neededWild = 0;

            // 检查第一张
            if (tempCounts2[key1] && tempCounts2[key1].count >= 1) {
                tempCounts2[key1].count--;
            } else {
                neededWild++;
            }

            // 检查第二张
            if (tempCounts2[key2] && tempCounts2[key2].count >= 1) {
                tempCounts2[key2].count--;
            } else {
                neededWild++;
            }

            // 检查第三张
            if (tempCounts2[key3] && tempCounts2[key3].count >= 1) {
                tempCounts2[key3].count--;
            } else {
                neededWild++;
            }

            if (tempWild2 >= neededWild) {
                tempWild2 -= neededWild;
                if (tryFormMianzi(tempCounts2, tempWild2, needed - 1)) {
                    return true;
                }
            }
        }
    }

    return false;
}

// 计算得分
function calculateScore(showedCards, huType) {
    // 基础分1分
    let score = 1;

    // 每个"发" +1分
    if (showedCards.fa) {
        score += showedCards.fa.length;
    }

    // 每个暗杠 +2分
    if (showedCards.gang) {
        score += showedCards.gang.length * 2;
    }

    // 特殊牌型加分（可选）
    // 七对 +1, 幺牌 +2, 浪牌 +3
    switch (huType) {
        case '七对':
            score += 1;
            break;
        case '幺牌':
            score += 2;
            break;
        case '浪牌':
            score += 3;
            break;
    }

    return score;
}

